actions.script:
try {
    document = darpan.audit.AuditReportAssembler.assembleReport(ec, companyUserGroupId, auditId, reportDate, period, generatedStamp)
} catch (IllegalArgumentException e) {
    ec.message.addError(e.message)
}

set.from:
darpan.audit.AuditReportAssembler.auditRuns(ec, companyUserGroupId, audits[0].getMap(), reportDate.toLocalDate())
                    .collect { [period: it.period, windowFromDate: java.sql.Date.valueOf(it.from), windowThruDate: java.sql.Date.valueOf(it.thru),
                                extendedThru: it.extendedThru ? java.sql.Date.valueOf(it.extendedThru) : null] }
